// Prepare writable pointers for major/minor/rev as required by the API
int major = 0, minor = 0, rev = 0;
// Invoke the target function
int rc = git_libgit2_version(&major, &minor, &rev);
// Enforce success per API contract and stop this fuzz path on failure
if (rc != 0) { FUZZ_BAIL(); }
// Property sanity: version numbers should be non-negative
if (major < 0 || minor < 0 || rev < 0) { FUZZ_BAIL(); }
// Nothing to persist; no outputs

// Call target; may return NULL (final release)
const char *pre = git_libgit2_prerelease();
// Do not free or modify the returned pointer; it is library-owned.
// Light touch to exercise non-NULL path without asserting formatting guarantees
if (pre) {
    volatile char c = pre[0];
    (void)c;
}
// No outputs

// Query compile-time/runtime feature bitmask
int features = git_libgit2_features();
// Interpret as bitwise OR of git_feature_t flags; no strict invariants to assert
volatile int sink = features; (void)sink;
// No outputs

// Choose a single valid git_feature_t flag (not a combined mask)
unsigned int r = *FUZZ_PARAM(unsigned int);
unsigned int idx = r % 12; // git_feature_t currently defines 12 bits [0..11]
