import os
import random
import string
from typing import List

# Data type: filesystem path string
# Goal: produce interesting but valid path strings for libgit2 fuzzers consuming
# FUZZ_PARAM_STR and FUZZ_PARAM_FILENAME where a filesystem path is expected.
# Constraints: return bytes <= 4096. Seeded randomness.

# Strategy:
# - Mix absolute/relative paths
# - Include components relevant to Git and libgit2: .git, objects, refs, HEAD,
#   config files (.gitconfig, .gitattributes, .gitmodules, .gitignore), FETCH_HEAD, etc.
# - Include variations like tilde (~), environment vars, dot / dotdot, unicode,
#   long components, multiple separators, trailing slashes.
# - Include Windows-style paths as well as POSIX to exercise cross-platform code.
# - Sometimes point to plausible Git directories like "repo/.git/objects" or
#   "repo/.git/refs/heads/main" to increase success of functions like git_odb_open.

POSIX_SEP = "/"
WIN_SEP = "\\"

_gits = [
    ".git",
    ".git/objects",
    ".git/objects/pack",
    ".git/refs",
    ".git/refs/heads",
    ".git/refs/tags",
    ".git/logs",
    ".git/hooks",
    ".git/info",
]

_gitfiles = [
    ".git/config",
    ".git/HEAD",
    ".gitattributes",
    ".gitignore",
    ".gitmodules",
    "FETCH_HEAD",
]

# Some branch-like names
_branches = ["main", "master", "dev", "feature/x", "bugfix/y", "release/1.0"]

# Some unicode path parts
_unicode_parts = [
    "café",
    "文件",
    "данные",
    "árvore",
    "δοκιμή",
    "тест",
]

# Safe filename characters
SAFE = string.ascii_letters + string.digits + "._-"


def _rand_choice(r: random.Random, arr: List[str]) -> str:
    return arr[r.randrange(len(arr))]


def _rand_component(r: random.Random) -> str:
    how = r.randrange(8)
    if how == 0:
        return _rand_choice(r, _unicode_parts)
    if how == 1:
        # random safe token
        n = r.randint(1, 12)
        return "".join(r.choice(SAFE) for _ in range(n))
    if how == 2:
        return "."
    if how == 3:
        return ".."
    if how == 4:
        return _rand_choice(r, _branches).replace("/", os.sep)
    if how == 5:
        return "submodule" + ("_" + str(r.randint(0, 999)))
    if how == 6:
        return "objects"
    return "refs"


def _maybe_env_prefix(r: random.Random, is_windows: bool) -> str:
    if r.random() < 0.2:
        if is_windows:
            # Common Windows env var style
            return "%USERPROFILE%" + ("\\" if r.random() < 0.5 else "")
        else:
            return "$HOME" + ("/" if r.random() < 0.5 else "")
    return ""


def _maybe_tilde_prefix(r: random.Random, is_windows: bool) -> str:
    if not is_windows and r.random() < 0.25:
        return "~" + ("/" if r.random() < 0.7 else "")
    return ""


def _sep(is_windows: bool) -> str:
    return WIN_SEP if is_windows else POSIX_SEP


def _join(parts: List[str], is_windows: bool) -> str:
    sep = _sep(is_windows)
    # Avoid duplicating separators excessively, but allow sometimes for interest
    cleaned = []
    for p in parts:
        if p == "":
            continue
        # Replace separators inside parts with the desired sep
        p = p.replace("/", sep).replace("\\", sep)
        cleaned.append(p)
    path = sep.join(cleaned)
    # Occasionally add trailing separator
    if cleaned and random.random() < 0.15:
        path += sep
    return path


def _make_git_like_path(r: random.Random, is_windows: bool) -> str:
    sep = _sep(is_windows)
    base = []
    # Optionally start with env or tilde
    pref = _maybe_env_prefix(r, is_windows) + _maybe_tilde_prefix(r, is_windows)
    if pref:
        base.append(pref)
    # Choose absolute vs relative
    if r.random() < 0.5:
        # absolute
        if is_windows:
            drive = chr(ord('C') + r.randrange(0, 3)) + ":" + WIN_SEP
            base.append(drive)
        else:
            base.append(POSIX_SEP)
    else:
        # relative repo-like directory
        base.append("repo_" + ''.join(r.choice(string.ascii_lowercase) for _ in range(r.randint(1,4))))
    # Add some components
    comp_count = r.randint(1, 5)
    for _ in range(comp_count):
        base.append(_rand_component(r))
    # Sometimes ensure we actually reference a git-related location
    if r.random() < 0.7:
        base.append(_rand_choice(r, _gits))
        if r.random() < 0.5:
            # maybe add refs/heads/<branch>
            base.append("refs")
            base.append("heads")
            base.append(_rand_choice(r, _branches).split("/")[-1])
    if r.random() < 0.4:
        base.append(_rand_choice(r, _gitfiles))
    # Occasional long single component to test limits but keep overall <= 4096
    if r.random() < 0.15:
        base.append("a" * r.randint(64, 180))
    path = _join(base, is_windows)
    return path


def _make_objects_dir(r: random.Random, is_windows: bool) -> str:
    # Specific helper to increase success for git_odb_open which expects .../objects
    sep = _sep(is_windows)
    prefix = _maybe_env_prefix(r, is_windows) + _maybe_tilde_prefix(r, is_windows)
    if r.random() < 0.5:
        if is_windows:
            root = chr(ord('D')) + ":" + WIN_SEP
        else:
            root = POSIX_SEP
    else:
        root = "repo" + str(r.randint(0, 999))
    parts = [p for p in [prefix, root, ".git", "objects"] if p]
    # Sometimes pack subdir
    if r.random() < 0.3:
        parts.append("pack")
    return _join(parts, is_windows)


def _make_simple_file(r: random.Random, is_windows: bool) -> str:
    # A simple relative path likely to exist or be acceptable
    leaf = _rand_choice(r, ["README.md", "src/main.c", "include/lib.h", "docs/guide.txt", "LICENSE"]) \
        .replace("/", _sep(is_windows))
    # Optional subdir
    if r.random() < 0.5:
        sub = _rand_choice(r, [".", "..", "tmp", "build", "test"]) \
            .replace("/", _sep(is_windows))
        return _join([sub, leaf], is_windows)
    return leaf


def _select_path(r: random.Random) -> str:
    is_windows = r.random() < 0.5
    choice = r.random()
    if choice < 0.30:
        return _make_git_like_path(r, is_windows)
    if choice < 0.55:
        return _make_objects_dir(r, is_windows)
    if choice < 0.80:
        return _make_simple_file(r, is_windows)
    # Construct a composite with many separators and dotted parts, but avoid leading absolute occasionally
    parts = []
    k = r.randint(2, 8)
    for _ in range(k):
        parts.append(_rand_component(r))
    return _join(parts, is_windows)


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Create multiple candidates and pick one that respects size and variety
    candidates = []
    for _ in range(8):
        p = _select_path(r)
        if not p:
            continue
        # Clamp overall size
        if len(p) > 4000:
            p = p[:4000]
        candidates.append(p)
    if not candidates:
        candidates = ["./.git/objects"]
    # Prefer those ending with objects for certain APIs sometimes
    prefer = [c for c in candidates if c.replace("\\", "/").endswith("/objects")]
    if prefer and r.random() < 0.5:
        chosen = _rand_choice(r, prefer)
    else:
        chosen = _rand_choice(r, candidates)
    return chosen.encode("utf-8", errors="surrogatepass")

import random
import string
from urllib.parse import quote

def _rand_hostname(rng: random.Random) -> str:
    # Generate a DNS-like hostname
    labels = []
    nlabels = rng.randint(1, 3)
    for _ in range(nlabels):
        length = rng.randint(1, 10)
        label_chars = string.ascii_lowercase + string.digits + "-"
        label = ''.join(rng.choice(label_chars) for _ in range(length)).strip('-') or 'host'
        labels.append(label)
    return '.'.join(labels)

def _rand_path(rng: random.Random) -> str:
    # Produce a URL path starting with '/'
    segs = []
    nsegs = rng.randint(1, 4)
    for _ in range(nsegs):
        seg_len = rng.randint(1, 12)
        seg_chars = string.ascii_letters + string.digits + "-_.@+"
        seg = ''.join(rng.choice(seg_chars) for _ in range(seg_len))
        segs.append(seg)
    return '/' + '/'.join(quote(s) for s in segs)

def _rand_file_url(rng: random.Random) -> str:
    # file:// URL. For fuzz harness this only needs syntactic validity.
    # Use a simple absolute path under /tmp-like prefix
    base = "/tmp"
    return "file://" + base + _rand_path(rng)

def _rand_http_url(rng: random.Random, secure: bool | None = None) -> str:
    if secure is None:
        secure = bool(rng.getrandbits(1))
    scheme = 'https' if secure else 'http'
    return f"{scheme}://{_rand_hostname(rng)}{_rand_path(rng)}"

def _rand_git_url(rng: random.Random) -> str:
    return f"git://{_rand_hostname(rng)}{_rand_path(rng)}"

def _rand_ssh_url(rng: random.Random) -> str:
    # ssh://[user@]host[:port]/path
    user = ''.join(rng.choice(string.ascii_lowercase + string.digits + '-_') for _ in range(rng.randint(3,8)))
    host = _rand_hostname(rng)
    port = f":{rng.randint(22, 65535)}" if rng.random() < 0.3 else ''
    return f"ssh://{user}@{host}{port}{_rand_path(rng)}"

def _rand_url(rng: random.Random) -> str:
    pick = rng.randint(0, 4)
    if pick == 0:
        return _rand_http_url(rng, secure=False)
    if pick == 1:
        return _rand_http_url(rng, secure=True)
    if pick == 2:
        return _rand_git_url(rng)
    if pick == 3:
        return _rand_ssh_url(rng)
    return _rand_file_url(rng)

def _rand_username(rng: random.Random) -> str:
    chars = string.ascii_letters + string.digits + "-_."
    ln = rng.randint(3, 16)
    return ''.join(rng.choice(chars) for _ in range(ln))

def _rand_password(rng: random.Random) -> str:
    chars = string.ascii_letters + string.digits + string.punctuation
    ln = rng.randint(6, 24)
    # avoid NUL/line breaks in typical fuzz strings
    pw = ''.join(rng.choice(chars) for _ in range(ln))
    return pw.replace('\n','-').replace('\r','-').replace('\x00','-')

def _rand_remote_name(rng: random.Random) -> str:
    # Valid remote names: letters, digits, '.', '_', '-'
    chars = string.ascii_letters + string.digits + '._-'
    ln = rng.randint(3, 16)
    name = ''.join(rng.choice(chars) for _ in range(ln))
    # Often use "origin" to drive different code paths
    if rng.random() < 0.4:
        name = 'origin'
    return name

def _rand_branch(rng: random.Random) -> str:
    # Reasonable branch name
    comps = []
    for _ in range(rng.randint(1, 3)):
        segchars = string.ascii_letters + string.digits + "-._"
        seg = ''.join(rng.choice(segchars) for _ in range(rng.randint(2, 12)))
        comps.append(seg)
    return '/'.join(comps)

def _assemble_corpus(urls: list[str], extra_strings: list[str]) -> bytes:
    # Join with NUL to help FUZZ_PARAM_STR extract discrete strings
    blob = bytearray()
    for s in urls + extra_strings:
        b = s.encode('utf-8', 'ignore')
        blob += b + b'\x00'
    # ensure size bound
    if len(blob) > 4096:
        return bytes(blob[:4096])
    return bytes(blob)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    urls = []
    # Provide a mixture of schemes used by the target stubs
    urls.append(_rand_file_url(rng))      # for file:// paths
    urls.append(_rand_http_url(rng, False))
    urls.append(_rand_http_url(rng, True))
    urls.append(_rand_git_url(rng))
    urls.append(_rand_ssh_url(rng))

    # Add several more random URLs to diversify
    for _ in range(rng.randint(3, 7)):
        urls.append(_rand_url(rng))

    # Additional strings that the stubs request via FUZZ_PARAM_STR
    extras = []
    # user-from-url, usernames, passwords
    for _ in range(3):
        extras.append(_rand_username(rng))
        extras.append(_rand_password(rng))
    # remote names and branches
    for _ in range(3):
        extras.append(_rand_remote_name(rng))
        extras.append(_rand_branch(rng))
    # some short path-like segments for submodule path/use
    for _ in range(3):
        seg = ''.join(rng.choice(string.ascii_letters + string.digits + '_/') for _ in range(rng.randint(3, 12)))
        if seg.startswith('/'):
            seg = seg.lstrip('/')
        extras.append(seg)

    # Ensure non-empty minimal strings exist
    extras.extend(['a', 'x', 'main'])

    return _assemble_corpus(urls, extras)

import random
import string
from typing import List

# Generator for valid Git revspec strings to exercise libgit2 revparse/revspec parsers.
# We create a mixture of common and diverse, yet valid specs:
# - simple names (HEAD, HEAD^, HEAD~N)
# - peel operators ^{tree}, ^{commit}
# - ranges A..B and A...B
# - refs under refs/heads/* and refs/tags/*
# - upstream/checkout reflog selectors (@{u}, @{upstream}, @{1})
# - abbreviated oid-like hex strings (sized realistically)
# - force inclusion of characters allowed in refnames
# Size kept <= 4096 bytes.

REF_SAFE_CHARS = string.ascii_letters + string.digits + "/-_."
HEX = "0123456789abcdef"


def _rand_ref_component(rng: random.Random, min_len=1, max_len=16) -> str:
    l = rng.randint(min_len, max_len)
    return "".join(rng.choice(REF_SAFE_CHARS) for _ in range(l))


def _rand_branch(rng: random.Random) -> str:
    kinds = [
        lambda: f"refs/heads/{_rand_ref_component(rng)}",
        lambda: f"refs/heads/{_rand_ref_component(rng)}/{_rand_ref_component(rng)}",
        lambda: f"refs/tags/{_rand_ref_component(rng)}",
        lambda: f"refs/remotes/origin/{_rand_ref_component(rng)}",
        lambda: "HEAD",
        lambda: "master",
        lambda: "main",
    ]
    return rng.choice(kinds)()


def _rand_hex_oid(rng: random.Random) -> str:
    # Abbreviated OIDs between 7 and 40 hex chars
    l = rng.randint(7, 40)
    return "".join(rng.choice(HEX) for _ in range(l))


def _ancestor_spec(rng: random.Random, base: str) -> str:
    # Use ~N or ^ (optionally with number)
    choice = rng.randint(0, 3)
    if choice == 0:
        n = rng.randint(1, 50)
        return f"{base}~{n}"
    elif choice == 1:
        return f"{base}^"
    elif choice == 2:
        n = rng.randint(1, 5)
        return f"{base}^{n}"
    else:
        # reflog selectors
        variant = rng.randint(0, 2)
        if variant == 0:
            return f"{base}@{{upstream}}"
        elif variant == 1:
            return f"{base}@{{1}}"
        else:
            return f"{base}@{{u}}"


def _peel_spec(rng: random.Random, base: str) -> str:
    return f"{base}^{{" + rng.choice(["tree", "commit", "tag"]) + "}}"


def _range_spec(rng: random.Random) -> str:
    # A..B (exclude A), or A...B (merge-base semantics)
    A_base = rng.choice([_rand_branch(rng), _rand_hex_oid(rng), "HEAD"])  # reasonable left
    B_base = rng.choice([_rand_branch(rng), _rand_hex_oid(rng), "HEAD"])  # reasonable right
    # Occasionally decorate with ancestors/peels
    if rng.random() < 0.6:
        A_base = _ancestor_spec(rng, A_base)
    if rng.random() < 0.4:
        B_base = _ancestor_spec(rng, B_base)
    if rng.random() < 0.3:
        A_base = _peel_spec(rng, A_base)
    if rng.random() < 0.2:
        B_base = _peel_spec(rng, B_base)
    sep = "..." if rng.random() < 0.5 else ".."
    return f"{A_base}{sep}{B_base}"


def _single_spec(rng: random.Random) -> str:
    base = rng.choice([
        "HEAD", "HEAD^", "HEAD~1", "HEAD^{tree}",
        _rand_branch(rng), _rand_hex_oid(rng)
    ])
    # Randomly extend with ancestor or peel
    roll = rng.random()
    if roll < 0.33:
        return _ancestor_spec(rng, base)
    elif roll < 0.66:
        return _peel_spec(rng, base)
    else:
        return base


def _revparse_like_set(rng: random.Random) -> List[str]:
    specs: List[str] = []
    # Ensure several useful canonical forms appear
    specs.append("HEAD")
    specs.append("HEAD^")
    specs.append("HEAD~2")
    specs.append("HEAD^{tree}")
    specs.append("HEAD^{commit}")
    specs.append("HEAD@{upstream}")
    # Add a few range forms
    for _ in range(4):
        specs.append(_range_spec(rng))
    # Add several branch names and decorated variants
    for _ in range(6):
        b = _rand_branch(rng)
        if rng.random() < 0.5:
            b = _ancestor_spec(rng, b)
        if rng.random() < 0.25:
            b = _peel_spec(rng, b)
        specs.append(b)
    # Include a couple of abbreviated OIDs
    for _ in range(3):
        o = _rand_hex_oid(rng)
        if rng.random() < 0.4:
            o = _ancestor_spec(rng, o)
        specs.append(o)
    return specs


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Build a corpus-like buffer with newline-separated revspecs so the harness
    # can consume FUZZ_PARAM_STR() repeatedly to get valid specs.
    specs = _revparse_like_set(rng)

    # Add a few extra randomized specs to diversify per-call
    extra = rng.randint(5, 12)
    for _ in range(extra):
        if rng.random() < 0.5:
            specs.append(_single_spec(rng))
        else:
            specs.append(_range_spec(rng))

    # Shuffle for variety
    rng.shuffle(specs)

    # Ensure non-empty strings and reasonable size
    joined = "\n".join(s for s in specs if s)
    data = joined.encode("utf-8")
    # Truncate safely to 4096 bytes if necessary (avoid cutting multibyte by slicing bytes)
    if len(data) > 4096:
        data = data[:4096]
    return data
